INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('9a298903-2cbf-5360-93e7-dcc62b2233f5', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$gmail-search$SR$, $SR$Overnight email$SR$, $SR${"query": "is:unread in:inbox newer_than:1d", "accountId": 2, "maxResults": 25, "fetchFullMessages": true}$SR$::jsonb, $SR${"x": 300, "y": 800}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('e6d6cc8a-0fdb-5c3d-8bbe-9d6b44237249', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$transform$SR$, $SR$Namespace: email$SR$, $SR${"expression": "// Only what triage needs: sender, subject, Gmail's labels. Bodies stay out\n// of the merge (and out of every downstream node's stored input).\nconst msgs = Array.isArray(input.messages) ? input.messages : null;\nreturn { email: {\n  count: input.count, messageIds: input.messageIds, error: input.error || null,\n  messages: msgs && msgs.map(function (m) { var h = m.headers || {};\n    return { headers: { from: h.from || '', subject: h.subject || '' }, labelIds: m.labelIds || [] }; })\n} };"}$SR$::jsonb, $SR${"x": 560, "y": 800}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('a953ebe6-261a-5060-8286-b7d17786cb72', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$merge$SR$, $SR$All signals$SR$, $SR${}$SR$::jsonb, $SR${"x": 1340, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('5efde8cc-d689-5711-9be7-5929032b9a53', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$briefing-compose$SR$, $SR$Compose: rank facts, gaps, sources$SR$, $SR${"timezone": "Europe/London", "titlePrefix": "Briefing", "auditRun": true}$SR$::jsonb, $SR${"x": 1600, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('dc7493f0-96f7-5c38-8358-d89e45f0be89', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$llm-call$SR$, $SR$Write the briefing$SR$, $SR${"model": "", "systemPrompt": "You write John's morning briefing: a short WhatsApp note from someone who has read everything so he does not have to.\n\nYou are given LEAD facts (most important first), BACKGROUND facts, a note on what kind of day it is, and GAPS.\n\nHOW TO WRITE\n- Open with one sentence giving the shape of the day — what is in the diary, how he slept, what the weather will do — drawn from LEAD.\n- Then 2 to 4 short bullets for the LEAD items that matter most, in order. Merge related facts into one bullet (sleep with readiness; diary items together).\n- If a LEAD fact is marked ACTION, finish with one line starting \"Today:\" naming the single most useful thing to do.\n- Use BACKGROUND only to add colour to a LEAD item, never as a bullet of its own.\n- A fact marked SAID YESTERDAY is worth repeating only if it still needs doing.\n- Plain, warm, direct British English. No preamble, no sign-off, no headings, at most one emoji. Under 110 words.\n\nTRUTH — code checks every draft; one that breaks these is thrown away and replaced by a plain list\n1. Every number, time, temperature and percentage must appear in LEAD or BACKGROUND exactly as written (09:30 may be written 9:30). Never calculate, round, convert or estimate. Do not restate the date.\n2. Units are already right (°C, km/h, km). Never Fahrenheit, miles or mph.\n3. Characterise something (a short night, a wet afternoon, a busy day) only when its value or its assessment line says so. Use the assessment's comparison; never make up your own.\n4. Leave GAPS out unless one is marked REQUIRED, and never fill a gap with a guess.\n5. Never invent an event, email, sender, alert or health figure.\n6. If LEAD and BACKGROUND are both empty, reply with exactly: No verified data this morning.", "userPrompt": "Today is {{input.briefing.dateLabel}}. {{input.modeNote}}\n\nLEAD\n{{input.leadSheet}}\n\nBACKGROUND\n{{input.backgroundSheet}}\n\nGAPS\n{{input.gapSheet}}", "temperature": 0.5, "maxTokens": 800, "_onError": {"mode": "continue"}}$SR$::jsonb, $SR${"x": 1860, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('037b85f4-3707-5c5a-8592-df2b8873ecdf', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$transform$SR$, $SR$Build record + message$SR$, $SR${"expression": "const b = input.briefing || {};\nconst md = (input.markdown || '').trim();\nconst gaps = input.gaps || [];\nconst sources = input.sources || [];\nconst ok = sources.filter(function (s) { return s.status === 'ok'; });\nconst now = new Date().toISOString();\nconst record = {\n  id: b.date,\n  trigger: 'workflow',\n  status: 'complete',\n  startedAt: b.generatedAt || now,\n  finishedAt: now,\n  title: b.title || 'Briefing',\n  markdown: md,\n  sources: ok.map(function (s) { return s.key; }),\n  llmCalls: 1,\n  costUsd: 0,\n  detail: {\n    headline: b.headline || '',\n    dateLabel: b.dateLabel || '',\n    generatedAt: b.generatedAt || now,\n    timezone: b.timezone || 'Europe/London',\n    mode: b.mode || null,\n    location: b.location || null,\n    weather: b.weather || null,\n    knowledge: b.knowledge || null,\n    memories: b.memories || [],\n    facts: input.facts || [],\n    gaps: gaps,\n    sources: sources,\n    ranking: input.ranking || null,\n    verification: {\n      verified: input.verified === true,\n      usedFallback: input.usedFallback === true,\n      violations: input.violations || [],\n      rejectedDraft: input.rejectedDraft || null\n    },\n    daydreamsText: input.daydreamsText || '',\n    daydreamsDay: input.daydreamsDay || null\n  }\n};\nconst lines = ['☕ ' + record.title];\n// The writer's opening line carries the day's shape; the code-written\n// headline is only needed when the prose was replaced or a required source is missing.\nif (b.headline && (input.verified !== true || b.truthCompromised)) lines.push(b.headline);\nif (md) { lines.push(''); lines.push(md); }\nconst notify = input.notifyGaps || [];\nif (notify.length) {\n  lines.push('');\n  lines.push('⚠ Not available today: ' + notify.join(', '));\n}\nif (input.daydreamsText) {\n  lines.push('');\n  lines.push('💭 Daydreams');\n  lines.push(input.daydreamsText);\n}\nlines.push('');\nlines.push('Full detail: https://strangeramblings.com/jkai/daydreams/briefing/' + record.id);\nif (b.mode === 'monday') lines.push('Reply \"briefing more <topic>\" or \"briefing less <topic>\" to tune it.');\nreturn { record: record, recordKey: record.id, whatsapp: lines.join('\\n') };"}$SR$::jsonb, $SR${"x": 2380, "y": 380}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('0fffbaf6-7c63-542b-92ae-d9002c117e70', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$database$SR$, $SR$Save briefing detail$SR$, $SR${"operation": "upsert", "collection": "briefings", "autoCreate": true, "key": "{{input.recordKey}}", "data": "{{input.record}}"}$SR$::jsonb, $SR${"x": 2640, "y": 300}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('680d27d2-ea7a-5688-b460-ba36bec9714d', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$whatsapp$SR$, $SR$Send summary$SR$, $SR${"to": "+447359228511", "message": "{{input.whatsapp}}", "formatMarkdown": true, "maxChunks": 3}$SR$::jsonb, $SR${"x": 2640, "y": 460}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('258c8729-84bd-59ea-84cb-d14a8442361e', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$postit$SR$, $SR$How this stays honest$SR$, $SR${"title": "Why this cannot fabricate", "color": "yellow", "text": "Every source is namespaced by its own transform, so provenance survives the merge.\n\nbriefing-compose decides what matters in CODE: baselines (last night vs your average), rain hours, diary, email from people, what was already said yesterday and your 👍/👎 votes. Each fact gets a salience and, where code can justify one, an assessment the writer may use.\n\nThe writer is free to sound like a person. briefing-verify then checks every number, time and unit in the draft against the facts it was shown; one invented figure and the draft is replaced by a plain list of the same facts. Failed sources stay in the ledger on the briefing page; only new or required gaps reach the message."}$SR$::jsonb, $SR${"x": 2640, "y": 620}$SR$::jsonb);
INSERT INTO workflow_nodes (id, workflow_id, type, label, config, position) VALUES ('057bdf2d-5b0a-56dc-a8fa-24e8cfb387a4', '0ad09fa0-5e17-40c2-9438-0604d6071a22', $SR$site-tool$SR$, $SR$Today's diary$SR$, $SR${"toolName": "apple_calendar_list", "args": {"dateRangeStart": "today", "dateRangeEnd": "+8d"}}$SR$::jsonb, $SR${"x": 300, "y": 920}$SR$::jsonb);
